<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { ElMessage } from "element-plus";
import { createAccount, getPublicSettings, listAccounts, listDepartments, updateMembership, updatePublicSettings, type Option } from "@/api/business";
const accounts=ref<any[]>([]),departments=ref<Option[]>([]),dialog=ref(false),settings=reactive({show_team:true,show_members:true,mask_members:true});
const form=reactive({username:"",name:"",password:"",department:undefined as number|undefined,role:"owner"});
async function load(){[accounts.value,departments.value]=await Promise.all([listAccounts(),listDepartments()]);Object.assign(settings,await getPublicSettings())}
async function create(){await createAccount(form);dialog.value=false;ElMessage.success("账号与部门授权已创建");await load()}
async function toggle(item:any){await updateMembership({user:item.user,department:item.department_id,role:item.role,active:!item.active});await load()}
async function saveSettings(){await updatePublicSettings(settings);ElMessage.success("全校公开设置已保存")}
onMounted(load);
</script>
<template><div class="page"><header><div><h2>账号与公开设置</h2><p>维护负责人、部门管理员授权和编号查验公开范围</p></div><el-button type="primary" @click="dialog=true">新增账号</el-button></header><section><h3>账号与部门授权</h3><el-table :data="accounts" border><el-table-column prop="username" label="账号"/><el-table-column prop="name" label="姓名"/><el-table-column label="授权"><template #default="s"><div v-for="m in s.row.memberships" :key="m.id" class="membership"><span>{{m.department__name}} · {{m.role==='admin'?'管理员':'负责人'}}</span><el-switch :model-value="m.active" @change="toggle({...m,user:s.row.id})"/></div></template></el-table-column></el-table></section><section><h3>公开查验字段</h3><el-checkbox v-model="settings.show_team">显示团队名称</el-checkbox><el-checkbox v-model="settings.show_members">显示成员姓名</el-checkbox><el-checkbox v-model="settings.mask_members" :disabled="!settings.show_members">成员姓名脱敏</el-checkbox><el-button type="primary" @click="saveSettings">保存设置</el-button></section><el-dialog v-model="dialog" title="新增账号与授权" width="520"><el-form label-position="top"><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password/></el-form-item><el-form-item label="部门"><el-select v-model="form.department" class="full"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item><el-form-item label="角色"><el-segmented v-model="form.role" :options="[{label:'负责人',value:'owner'},{label:'部门管理员',value:'admin'}]"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :disabled="!form.username||!form.password||!form.department" @click="create">创建</el-button></template></el-dialog></div></template>
<style scoped>.page{padding:20px}header{display:flex;justify-content:space-between;margin-bottom:18px}h2{margin:0;font-size:20px;letter-spacing:0}p{color:#73767a}section{padding:18px 0;border-top:1px solid #ebeef5}h3{font-size:16px;letter-spacing:0}.membership{display:flex;align-items:center;justify-content:space-between;max-width:420px;padding:3px 0}.full{width:100%}</style>
